    if (/^func (?:\([^)]*\)\s+)?([A-Z][A-Za-z0-9_]*)/) {
      $decls{"$pkg\t$1"} = $rel;
    }
  }
  close $fh;
}

my %fanin; $fanin{$_}=0 for keys %decls;

